"""Lightweight portable shorts renderer: one FFmpeg pass with word captions."""
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import time
from engine.reel_captions import ass_document, reel_words
from engine.portable_encoder import selected_encoder, device_args, codec_args

def render(source_path, highlights, transcript_path, output_dir, use_cache=False, aspect_ratio="9:16"):
    source=Path(source_path)
    folder=Path(output_dir)
    folder.mkdir(parents=True,exist_ok=True)
    data=json.loads(Path(transcript_path).read_text(encoding="utf-8-sig")) if Path(transcript_path).is_file() else {}
    width,height={"9:16":(720,1280),"16:9":(1280,720),"1:1":(720,720),"4:5":(720,900)}.get(aspect_ratio,(720,1280))
    exe=shutil.which("ffmpeg")
    if not exe:
        raise RuntimeError("Bundled FFmpeg is not on PATH.")
    encoder=selected_encoder()
    print(f"[Log] Fast encoder: {encoder} (CPU filters, 4 Mbps H.264).",flush=True)
    outputs=[]
    started=time.perf_counter()
    for i,hi in enumerate(highlights,1):
        a,b=float(hi["start"]),float(hi["end"])
        if b-a<0.5:
            continue
        output=folder/f"video_clip_{i}.mp4"
        marker=Path(str(output)+".fast-key")
        signature=hashlib.sha256(repr([str(source.resolve()),source.stat().st_size,a,b,width,height,encoder,"fast-v2-4Mbps"]).encode()).hexdigest()
        if use_cache and output.is_file() and output.stat().st_size>1000 and marker.is_file() and marker.read_text()==signature:
            print(f"[Log] Fast clip {i} already complete; reusing it.",flush=True)
            outputs.append(str(output))
            continue
        ass=folder/f"fast_clip_{i}.ass"
        ass.write_text(ass_document(reel_words([(a,b,b-a)],data),size=(width,height),font="Arial",font_size=round(height*0.05)),encoding="utf-8-sig")
        filters=f"scale={width}:{height}:force_original_aspect_ratio=decrease,pad={width}:{height}:(ow-iw)/2:(oh-ih)/2:color=black,setsar=1,ass={ass.name}"
        pending=folder/f"fast_pending_{i}.mp4"
        cmd=[exe,"-hide_banner","-loglevel","error","-nostdin","-y",*device_args(encoder),"-ss",str(a),"-i",str(source.resolve()),"-t",str(b-a),
             "-map","0:v:0","-map","0:a:0?","-vf",filters,"-r","30",*codec_args(encoder),"-c:a","aac","-b:a","128k","-movflags","+faststart",pending.name]
        t=time.perf_counter()
        try:
            subprocess.run(cmd,cwd=folder,check=True)
        except subprocess.CalledProcessError:
            if encoder != "intel":
                raise
            print("[Warning] Intel encoding failed; retrying this clip on CPU.",flush=True)
            # Remove hardware init and replace only the encoding options; keep all filters/audio.
            start=cmd.index("-init_hw_device")
            del cmd[start:start+2]
            start=cmd.index("-c:v")
            end=cmd.index("-c:a")
            cmd[start:end]=codec_args("cpu")
            subprocess.run(cmd,cwd=folder,check=True)
        os.replace(pending,output)
        marker.write_text(signature)
        outputs.append(str(output))
        print(f"[Log] Fast clip {i} saved in {time.perf_counter()-t:.1f}s.",flush=True)
    print(f"[Log] Fast render total: {time.perf_counter()-started:.1f}s.",flush=True)
    return outputs

